/**
 * How Chrysanthemum round (`kiku-no-maru`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/kiku-no-maru";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"A flower of pointed petals and broad veined leaves stands against a fine ring. One curved stalk rises from the ring to the flower.","ja":"細い輪の内側に、先のとがった花びらの菊と葉脈のある幅広い葉を置きます。曲がった茎が輪から花へ伸びます。"};

export default construction;
export { construction, description };
